import "server-only";
import { randomUUID } from "node:crypto";
import type postgres from "postgres";
import { crmDatabase, fakeRows, text, CrmProblem } from "@/lib/pramaan/crm-data";
import { capability } from "@/lib/pramaan/server";
import { mayModerate, moderationSubject, socialScope } from "@/lib/pramaan/social-context";
export type Target = { kind: "item" | "person"; ref: string };
export type Subject = { label: string; href?: string; excerpt?: string };
export type Report = Target & { id: string; reason: string; by: string; at: string; status: "open" | "hidden" | "dismissed"; automatic: boolean; decidedBy?: string; decidedAt?: string; subject?: Subject };
/** What reviewers receive: plain labels, without member or content references. */
export type QueueReport = Pick<Report, "id" | "kind" | "reason" | "at" | "status" | "automatic" | "decidedAt"> & { reviewer?: "you" | "another moderator"; subject?: Subject };
export type ModerationData = { reports: QueueReport[] };
export type AuditEntry = { action: "hide" | "dismiss"; by: string; at: string; target: Target };
type Scoped<T> = T & { scope: string };
/** Reviewers see open reports first, then the most recent decisions. */
const QUEUE_LIMIT = 200;
const isFake = () => process.env.PRAMAAN_FAKE === "1";
const iso = (value: Date | string | null) => value === null ? undefined : new Date(value).toISOString();
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
export function targetOf(body: Record<string, unknown>): Target {
  if (body.kind !== "item" && body.kind !== "person") throw new CrmProblem("Choose an item or person.");
  return { kind: body.kind, ref: text(body.ref, "a reference", 200) };
}
export async function isBlocked(viewer: string | undefined, other: string, scope = socialScope()) {
  if (!viewer) return false;
  if (isFake()) return fakeRows<Scoped<{ viewer: string; other: string }>>("crm_block").some(b => b.scope === scope && b.viewer === viewer && b.other === other);
  return (await crmDatabase()`select 1 from crm_block where scope = ${scope} and viewer = ${viewer} and other = ${other}`).length > 0;
}
export async function isHidden(ref: string, scope = socialScope()) {
  if (isFake()) return fakeRows<Scoped<{ ref: string }>>("crm_hidden_item").some(h => h.scope === scope && h.ref === ref);
  return (await crmDatabase()`select 1 from crm_hidden_item where scope = ${scope} and ref = ${ref}`).length > 0;
}
/** A block in either direction: the blocker stops seeing the person, and a blocked person sees nothing of the blocker. */
export async function blockedEitherWay(viewer: string | undefined, other: string, scope = socialScope()) {
  return !!viewer && (await isBlocked(viewer, other, scope) || await isBlocked(other, viewer, scope));
}
/** Whether the viewer may see this person's item. Use it for one item; use `visibleSql` for a list. */
export async function canSee(scope: string, viewer: string, author: string, ref: string) {
  return !await isHidden(ref, scope) && !await blockedEitherWay(viewer, author, scope);
}
/** `blockedEitherWay` inside a list query, so a page of results stays full and cursors stay correct. */
export function notBlockedSql(scope: string, viewer: string, author: postgres.Fragment) {
  return crmDatabase()`not exists (select 1 from crm_block b where b.scope = ${scope} and ((b.viewer = ${viewer} and b.other = ${author}) or (b.viewer = ${author} and b.other = ${viewer})))`;
}
/** `canSee` inside a list query. */
export function visibleSql(scope: string, viewer: string, author: postgres.Fragment, ref: postgres.Fragment) {
  return crmDatabase()`not exists (select 1 from crm_hidden_item h where h.scope = ${scope} and h.ref = ${ref}) and ${notBlockedSql(scope, viewer, author)}`;
}
export async function reportTarget(scope: string, by: string, target: Target, reason: string, automatic = false, subject?: Subject) {
  const why = text(reason, "a reason", 1000);
  if (isFake()) {
    const reports = fakeRows<Scoped<Report>>("crm_report");
    const open = reports.find(r => r.scope === scope && r.by === by && r.kind === target.kind && r.ref === target.ref && r.status === "open");
    if (open) { open.subject = subject ?? open.subject; return; }
    reports.push({ scope, ...target, id: randomUUID(), by, reason: why, at: new Date().toISOString(), status: "open", automatic, subject });
    return;
  }
  // The partial unique index keeps one open report per reporter and target, even under races.
  // A repeat keeps that report and shows its reviewer the newest words, as when the check runs on an edit.
  await crmDatabase()`insert into crm_report (id, scope, kind, ref, reason, reported_by, automatic, subject)
    values (${randomUUID()}, ${scope}, ${target.kind}, ${target.ref}, ${why}, ${by}, ${automatic}, ${subject ? JSON.stringify(subject) : null}::text::jsonb)
    on conflict (scope, reported_by, kind, ref) where status = 'open' do update set subject = coalesce(excluded.subject, crm_report.subject)`;
}
function refuseDecision(report: { kind: string; status: string } | undefined, action: "hide" | "dismiss") {
  if (!report) throw new CrmProblem("This report is no longer available.", 404);
  if (report.status !== "open") throw new CrmProblem("This report was already reviewed.", 409);
  if (action === "hide" && report.kind !== "item") throw new CrmProblem("Only items can be hidden. Dismiss this report or use your host's account controls.");
}
async function decide(scope: string, member: string, id: string, action: "hide" | "dismiss") {
  const status = action === "hide" ? "hidden" : "dismissed";
  if (isFake()) {
    const report = fakeRows<Scoped<Report>>("crm_report").find(r => r.scope === scope && r.id === id);
    refuseDecision(report, action);
    const at = new Date().toISOString();
    Object.assign(report!, { status, decidedBy: member, decidedAt: at });
    const hidden = fakeRows<Scoped<{ ref: string; by: string; at: string }>>("crm_hidden_item");
    if (action === "hide" && !hidden.some(h => h.scope === scope && h.ref === report!.ref)) hidden.push({ scope, ref: report!.ref, by: member, at });
    fakeRows<Scoped<AuditEntry>>("crm_moderation_audit").push({ scope, action, by: member, at, target: { kind: report!.kind, ref: report!.ref } });
    return;
  }
  await crmDatabase().begin(async tx => {
    // Only an open report changes, so one of two concurrent reviewers wins.
    const [report] = await tx`update crm_report set status = ${status}, decided_by = ${member}, decided_at = now()
      where scope = ${scope} and id = ${id} and status = 'open' and (${action} = 'dismiss' or kind = 'item')
      returning kind, ref, decided_at`;
    if (!report) {
      const [existing] = await tx`select kind, status from crm_report where scope = ${scope} and id = ${id}`;
      refuseDecision(existing as { kind: string; status: string } | undefined, action);
      throw new CrmProblem("This report was already reviewed.", 409);
    }
    if (action === "hide") await tx`insert into crm_hidden_item (scope, ref, hidden_by, hidden_at) values (${scope}, ${report.ref}, ${member}, ${report.decided_at}) on conflict do nothing`;
    await tx`insert into crm_moderation_audit (scope, report_id, action, actor, at, kind, ref) values (${scope}, ${id}, ${action}, ${member}, ${report.decided_at}, ${report.kind}, ${report.ref})`;
  });
}
export async function moderate(scope: string, member: string, body: Record<string, unknown>) {
  if (body.action === "report") {
    const target = targetOf(body);
    // Looked up here, never taken from the browser, and kept so a later edit doesn't change what reviewers read.
    const subject = await moderationSubject(target.kind, target.ref, scope);
    await reportTarget(scope, member, target, text(body.reason, "a reason", 1000), false, subject.excerpt ? subject : undefined);
    return { message: "Report sent." };
  }
  if (body.action === "block" || body.action === "unblock") {
    const other = text(body.ref, "a person", 200);
    if (other === member) throw new CrmProblem("Choose another person.");
    if (isFake()) {
      const blocks = fakeRows<Scoped<{ viewer: string; other: string }>>("crm_block");
      const at = blocks.findIndex(b => b.scope === scope && b.viewer === member && b.other === other);
      if (at >= 0) blocks.splice(at, 1);
      if (body.action === "block") blocks.push({ scope, viewer: member, other });
    } else if (body.action === "block") {
      await crmDatabase()`insert into crm_block (scope, viewer, other) values (${scope}, ${member}, ${other}) on conflict do nothing`;
    } else {
      await crmDatabase()`delete from crm_block where scope = ${scope} and viewer = ${member} and other = ${other}`;
    }
    return { message: body.action === "block" ? "Person blocked." : "Person unblocked." };
  }
  if (!await mayModerate(member, scope)) throw new CrmProblem("Only owners and admins can review reports.", 403);
  if (body.action !== "hide" && body.action !== "dismiss") throw new CrmProblem("Choose a review action.");
  if (typeof body.id !== "string" || !UUID.test(body.id)) throw new CrmProblem("This report is no longer available.", 404);
  await decide(scope, member, body.id, body.action);
  return { message: "Review saved." };
}
/** Off by default. Classification is advisory: it never hides or deletes content. */
export async function checkNewText(scope: string, target: Target, content: string, subject?: Subject) {
  if (process.env.PRAMAAN_TEXT_SCREENING !== "1" || !content.trim()) return;
  let reason = "Automatic text check needs a review.";
  try {
    const result = await capability<{ primaryCategory?: string; confidence?: number; allCategories?: { category?: string; confidence?: number }[] }>("text.classify", { text: content });
    const labels = [{ category: result.primaryCategory, confidence: result.confidence }, ...(result.allCategories ?? [])];
    const flagged = labels.some(c => /^(abusive|spam|sexual)$/i.test(c.category ?? "") && typeof c.confidence === "number" && c.confidence >= 0.7);
    const safe = !flagged && labels.some(c => c.category?.toLowerCase() === "safe" && typeof c.confidence === "number" && c.confidence >= 0.7 && c.confidence <= 1);
    if (safe) return;
    if (flagged) reason = "Automatic text check flagged this for review.";
  } catch { /* A failed check stays visible and goes to a person for review. */ }
  await reportTarget(scope, "automatic", target, reason, true, subject);
}

async function recentReports(scope: string): Promise<Report[]> {
  if (isFake()) {
    return fakeRows<Scoped<Report>>("crm_report").filter(r => r.scope === scope).reverse()
      .sort((a, b) => Number(b.status === "open") - Number(a.status === "open") || b.at.localeCompare(a.at)).slice(0, QUEUE_LIMIT).map(r => structuredClone(r));
  }
  // ponytail: one bounded page of 200; add cursor paging when a community keeps more open reports than that.
  const rows = await crmDatabase()`select * from crm_report where scope = ${scope} order by (status = 'open') desc, reported_at desc limit ${QUEUE_LIMIT}`;
  return rows.map(r => ({ id: r.id, kind: r.kind, ref: r.ref, reason: r.reason, by: r.reported_by, at: iso(r.reported_at)!, status: r.status, automatic: r.automatic, decidedBy: r.decided_by ?? undefined, decidedAt: iso(r.decided_at), subject: r.subject ?? undefined }));
}
/** Only call after verifying the viewer's moderator role. */
export async function moderationQueue(scope: string, viewer?: string): Promise<ModerationData> {
  const reports = await recentReports(scope);
  return { reports: await Promise.all(reports.map(async r => ({
    id: r.id, kind: r.kind, reason: r.reason, at: r.at, status: r.status, automatic: r.automatic,
    ...(r.decidedAt ? { decidedAt: r.decidedAt, reviewer: r.decidedBy === viewer ? "you" as const : "another moderator" as const } : {}),
    subject: r.subject ?? await moderationSubject(r.kind, r.ref, scope),
  }))) };
}
/** Who decided what and when, newest first. Only call after verifying the viewer's moderator role. */
export async function moderationAudit(scope: string, limit = 100): Promise<AuditEntry[]> {
  if (isFake()) return fakeRows<Scoped<AuditEntry>>("crm_moderation_audit").filter(a => a.scope === scope).reverse().slice(0, limit).map(({ scope: _scope, ...entry }) => structuredClone(entry));
  const rows = await crmDatabase()`select action, actor, at, kind, ref from crm_moderation_audit where scope = ${scope} order by at desc, id desc limit ${limit}`;
  return rows.map(r => ({ action: r.action, by: r.actor, at: iso(r.at)!, target: { kind: r.kind, ref: r.ref } }));
}

import "server-only";
import { currentMemberId } from "@/lib/pramaan/session";
import { CrmProblem, crmDatabase, fakeRows } from "@/lib/pramaan/crm-data";
import { clientIp, limitPublic, verifyPublicBot, PUBLIC_READ_LIMIT, PUBLIC_WINDOW_MS, PUBLIC_WRITE_LIMIT } from "@/lib/pramaan/public-guard";
import { PramaanError } from "@pramaan/sdk";

/** Wire these two lookups to trusted host membership data before enabling production. */
export function socialScope() {
  const scope = process.env.PRAMAAN_SOCIAL_SCOPE || (process.env.PRAMAAN_FAKE === "1" ? "demo" : "");
  if (!scope) throw new CrmProblem("This community is not connected yet.", 503);
  return scope;
}
export async function socialContext(request: Request) {
  const member = await currentMemberId(request);
  return { member, scope: socialScope() };
}
export async function mayModerate(member: string, _scope: string): Promise<boolean> {
  return process.env.PRAMAAN_FAKE === "1" && ["mbr_owner", "mbr_admin"].includes(member);
}
export function requireMember(member: string | undefined): asserts member is string {
  if (!member) throw new CrmProblem("Sign in to continue.", 401);
}
function refuseForeignOrigin(request: Request) {
  const origin = request.headers.get("origin");
  if (origin && origin !== new URL(process.env.PRAMAAN_SOCIAL_ORIGIN || request.url).origin) throw new CrmProblem("Please reload the page and try again.", 403);
}
export async function protectSocial(request: Request, body: Record<string, unknown> = {}) {
  const write = request.method !== "GET";
  if (write) refuseForeignOrigin(request);
  // Count first, so a flood of requests cannot run up bot-check calls.
  limitPublic(`social:${request.method}`, clientIp(request), write ? PUBLIC_WRITE_LIMIT : PUBLIC_READ_LIMIT, PUBLIC_WINDOW_MS);
  if (write) await verifyPublicBot(request, body.botCheckToken);
}
const MEMBER_WRITE_LIMIT = 60;
const MEMBER_READ_LIMIT = 240;
const SHARED_ADDRESS_MULTIPLIER = 10;
/**
 * For signed-in screens that write and poll often, such as a feed or a conversation. Each person has
 * their own limit; one address gets room for a shared office, so `protectSocial`'s ten writes a minute
 * would not stop a normal conversation.
 */
export async function protectMember(request: Request, body: Record<string, unknown> = {}) {
  const write = request.method !== "GET";
  if (write) refuseForeignOrigin(request);
  limitPublic(`member:${request.method}`, clientIp(request), (write ? PUBLIC_WRITE_LIMIT : PUBLIC_READ_LIMIT) * SHARED_ADDRESS_MULTIPLIER, PUBLIC_WINDOW_MS);
  const { scope, member } = await socialContext(request);
  requireMember(member);
  limitPublic(`person:${request.method}`, member, write ? MEMBER_WRITE_LIMIT : MEMBER_READ_LIMIT, PUBLIC_WINDOW_MS);
  if (write) await verifyPublicBot(request, body.botCheckToken);
  return { scope, member };
}
export function socialError(error: unknown) {
  const status = error instanceof CrmProblem ? error.status : error instanceof PramaanError ? error.status ?? 503 : 500;
  // Never expose a remote error, database detail or internal reference.
  const message = error instanceof CrmProblem ? error.message : status === 429 ? "Too many requests. Please try again later." : "Couldn't finish that. Please try again.";
  return Response.json({ error: { message } }, { status, headers: { "Cache-Control": "no-store" } });
}
export const socialResponse = (data: unknown) => Response.json(data, { headers: { "Cache-Control": "no-store" } });

/** Wire to the person's confirmed address. Undefined sends nothing; never use an address from a form. */
export async function memberEmail(person: string, _scope: string): Promise<string | undefined> {
  return process.env.PRAMAAN_FAKE === "1" ? `${person}@example.com` : undefined;
}

/** Replace with a local, scope-checked content lookup in the consuming kit. */
export async function moderationSubject(kind: "item" | "person", ref: string, scope: string): Promise<{ label: string; href?: string; excerpt?: string }> {
  if (process.env.PRAMAAN_FAKE === "1" && ref === "demo-item") return { label: "Sample community post", excerpt: "A sample post for trying the review controls." };
  if (kind === "person") return { label: "Reported person", href: `/profiles/${encodeURIComponent(ref)}` };
  return await listingSubject(ref, scope) ?? { label: "Reported item" };
}
const LISTING_REF = /^listing:([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/i;
/** The listings block's reports. Anyone can submit any reference, and the table may not be installed. */
async function listingSubject(ref: string, scope: string) {
  const id = LISTING_REF.exec(ref)?.[1];
  if (!id) return undefined;
  const [row] = process.env.PRAMAAN_FAKE === "1"
    ? fakeRows<{ scope: string; id: string; title: string; description: string }>("crm_listing").filter(l => l.scope === scope && l.id === id)
    : await crmDatabase()`select title, description from crm_listing where scope = ${scope} and id = ${id}`.catch(() => []);
  return row && listingSubjectOf({ title: row.title, description: row.description });
}
/** What reviewers read about a listing, stored on its report. */
export const listingSubjectOf = (listing: { title: string; description: string }) => ({ label: `Listing: ${listing.title}`, excerpt: String(listing.description).slice(0, 240) });

import "server-only";
import { randomUUID } from "node:crypto";
import { readFile } from "node:fs/promises";
import { request } from "node:http";
import path from "node:path";
import { after } from "next/server";
import { crmDatabase, fakeRows, text, CrmProblem } from "@/lib/pramaan/crm-data";
import { blockedEitherWay, isHidden, moderate, notBlockedSql, reportTarget } from "@/lib/pramaan/moderation";
import { memberEmail } from "@/lib/pramaan/social-context";

/** `name` is only ever the person's public display name. `ref` is never shown. */
export type Conversation = { id: string; person: { ref: string; name?: string }; preview?: string; at?: string; unread: number };
export type Message = { id: string; mine: boolean; text: string; at: string; read: boolean };
export type Thread = { id: string; person: Conversation["person"]; messages: Message[]; earlier?: string };
type ConversationRow = { id: string; scope: string; a: string; b: string; startedBy: string; readA: number; readB: number; lastAt?: string; createdAt: string };
type MessageRow = { id: string; seq: number; scope: string; conversationId: string; sender: string; body: string; at: string };

const SHOWN = 50;
const CONVERSATIONS_SHOWN = 100;
const isFake = () => process.env.PRAMAAN_FAKE === "1";
const iso = (value: Date | string | null | undefined) => value ? new Date(value).toISOString() : undefined;
const messageRef = (id: string) => `message:${id}`;
const gone = () => new CrmProblem("This conversation isn't available.", 404);
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const idOf = (value: unknown) => {
  if (typeof value !== "string" || !UUID.test(value)) throw gone();
  return value.toLowerCase();
};
const fakeConversations = () => fakeRows<ConversationRow>("crm_conversation");
const fakeMessages = () => fakeRows<MessageRow>("crm_message");
function fakeSeq() { const seq = fakeRows<number>("crm_message_seq"); seq.push(0); return seq.length; }
function fakeName(scope: string, person: string) {
  const profile = fakeRows<{ scope: string; person: string; name: string; public: { name: boolean } }>("crm_profile").find(p => p.scope === scope && p.person === person);
  return profile?.public.name && profile.name ? profile.name : undefined;
}
const person = (ref: string, name: string | null | undefined) => ({ ref, ...(name ? { name } : {}) });

export async function conversationList(scope: string, member: string): Promise<{ conversations: Conversation[] }> {
  if (isFake()) {
    const rows = fakeConversations().filter(c => c.scope === scope && (c.a === member || c.b === member) && (c.lastAt || c.startedBy === member));
    const out: Conversation[] = [];
    for (const c of rows) {
      const other = c.a === member ? c.b : c.a;
      if (await blockedEitherWay(member, other, scope)) continue;
      const seen = c.a === member ? c.readA : c.readB;
      const shown: MessageRow[] = [];
      for (const m of fakeMessages().filter(m => m.conversationId === c.id)) if (!await isHidden(messageRef(m.id), scope)) shown.push(m);
      const last = shown.at(-1);
      out.push({ id: c.id, person: person(other, fakeName(scope, other)), ...(last ? { preview: last.body.slice(0, 120), at: last.at } : {}), unread: shown.filter(m => m.seq > seen && m.sender !== member).length });
    }
    return { conversations: out.sort((x, y) => (y.at ?? "").localeCompare(x.at ?? "")).slice(0, CONVERSATIONS_SHOWN) };
  }
  const sql = crmDatabase();
  const shown = sql`not exists (select 1 from crm_hidden_item h where h.scope = ${scope} and h.ref = ${"message:"} || x.id::text)`;
  // ponytail: the 100 most recent conversations; add cursor paging for people with more than that.
  const rows = await sql`select c.id, me.other, me.seen, case when n.public_name then nullif(n.name, '') end as other_name, last.body as preview, last.created_at as last_message_at,
      (select count(*)::int from crm_message x where x.conversation_id = c.id and x.seq > me.seen and x.sender <> ${member} and ${shown}) as unread
    from crm_conversation c
    cross join lateral (select case when c.person_a = ${member} then c.person_b else c.person_a end as other, case when c.person_a = ${member} then c.read_a else c.read_b end as seen) me
    left join crm_profile n on n.scope = c.scope and n.person = me.other
    left join lateral (select x.body, x.created_at from crm_message x where x.conversation_id = c.id and ${shown} order by x.seq desc limit 1) last on true
    where c.scope = ${scope} and (c.person_a = ${member} or c.person_b = ${member}) and (c.last_at is not null or c.started_by = ${member})
      and ${notBlockedSql(scope, member, sql`me.other`)}
    order by coalesce(c.last_at, c.created_at) desc limit ${CONVERSATIONS_SHOWN}`;
  return { conversations: rows.map(r => ({ id: r.id, person: person(r.other, r.other_name), ...(r.preview ? { preview: String(r.preview).slice(0, 120), at: iso(r.last_message_at) } : {}), unread: r.unread })) };
}
type Open = { other: string; mineIsA: boolean; seen: number; theirs: number };
/** Only a participant gets past this, and never across a block. The answer is the same for a stranger as for a missing id. */
async function openConversation(scope: string, member: string, id: string): Promise<Open> {
  let row: { a: string; b: string; readA: number | string; readB: number | string } | undefined;
  if (isFake()) row = fakeConversations().find(c => c.scope === scope && c.id === id);
  else row = (await crmDatabase()`select person_a as a, person_b as b, read_a as "readA", read_b as "readB" from crm_conversation where scope = ${scope} and id = ${id}`)[0] as never;
  if (!row || (row.a !== member && row.b !== member)) throw gone();
  const mineIsA = row.a === member;
  const other = mineIsA ? row.b : row.a;
  if (await blockedEitherWay(member, other, scope)) throw gone();
  return { other, mineIsA, seen: Number(mineIsA ? row.readA : row.readB), theirs: Number(mineIsA ? row.readB : row.readA) };
}
function validCursor(cursor: string | null | undefined) {
  if (!cursor) return undefined;
  if (!/^\d{1,18}$/.test(cursor)) throw new CrmProblem("Reload to see the latest messages.");
  return cursor;
}
export async function thread(scope: string, member: string, conversation: string, before?: string | null): Promise<Thread> {
  const id = idOf(conversation);
  const open = await openConversation(scope, member, id);
  const cursor = validCursor(before);
  const shape = (m: { id: string; seq: number; sender: string; body: string; at: string }): Message => ({ id: m.id, mine: m.sender === member, text: m.body, at: m.at, read: m.sender === member && m.seq <= open.theirs });
  let rows: { id: string; seq: number; sender: string; body: string; at: string }[] = [];
  let name: string | undefined;
  if (isFake()) {
    name = fakeName(scope, open.other);
    const newest = fakeMessages().filter(m => m.conversationId === id && (!cursor || m.seq < Number(cursor))).sort((x, y) => y.seq - x.seq);
    for (const m of newest) {
      if (rows.length > SHOWN) break;
      if (!await isHidden(messageRef(m.id), scope)) rows.push(m);
    }
  } else {
    const sql = crmDatabase();
    const [profile] = await sql`select case when public_name then nullif(name, '') end as name from crm_profile where scope = ${scope} and person = ${open.other}`;
    name = profile?.name ?? undefined;
    const found = await sql`select x.id, x.seq, x.sender, x.body, x.created_at from crm_message x
      where x.conversation_id = ${id} and ${cursor ? sql`x.seq < ${cursor}::bigint` : sql`true`}
        and not exists (select 1 from crm_hidden_item h where h.scope = ${scope} and h.ref = ${"message:"} || x.id::text)
      order by x.seq desc limit ${SHOWN + 1}`;
    rows = found.map(m => ({ id: m.id, seq: Number(m.seq), sender: m.sender, body: m.body, at: iso(m.created_at)! }));
  }
  const page = rows.slice(0, SHOWN);
  return { id, person: person(open.other, name), messages: page.map(shape).reverse(), ...(rows.length > SHOWN ? { earlier: String(page[SHOWN - 1].seq) } : {}) };
}
async function start(scope: string, member: string, body: Record<string, unknown>) {
  const other = text(body.person, "a person", 200);
  if (other === member) throw new CrmProblem("Choose another person.");
  if (await blockedEitherWay(member, other, scope)) throw new CrmProblem("This person can't be messaged.", 404);
  const [a, b] = member < other ? [member, other] : [other, member];
  if (isFake()) {
    let row = fakeConversations().find(c => c.scope === scope && c.a === a && c.b === b);
    if (!row) fakeConversations().push(row = { id: randomUUID(), scope, a, b, startedBy: member, readA: 0, readB: 0, createdAt: new Date().toISOString() });
    return { id: row.id };
  }
  const sql = crmDatabase();
  // Two people starting at once land on the same row.
  await sql`insert into crm_conversation (id, scope, person_a, person_b, started_by) values (${randomUUID()}, ${scope}, ${a}, ${b}, ${member}) on conflict (scope, person_a, person_b) do nothing`;
  const [row] = await sql`select id from crm_conversation where scope = ${scope} and person_a = ${a} and person_b = ${b}`;
  return { id: row.id as string };
}
async function send(scope: string, member: string, body: Record<string, unknown>) {
  const conversationId = idOf(body.id);
  const content = text(body.text, "a message", 4000);
  const open = await openConversation(scope, member, conversationId);
  const id = randomUUID();
  let firstUnread: boolean;
  if (isFake()) {
    firstUnread = !fakeMessages().some(m => m.conversationId === conversationId && m.sender === member && m.seq > open.theirs);
    const at = new Date().toISOString();
    fakeMessages().push({ id, seq: fakeSeq(), scope, conversationId, sender: member, body: content, at });
    fakeConversations().find(c => c.id === conversationId)!.lastAt = at;
  } else {
    firstUnread = await crmDatabase().begin(async tx => {
      const [earlier] = await tx`select 1 from crm_message where conversation_id = ${conversationId} and sender = ${member} and seq > ${open.theirs} limit 1`;
      await tx`insert into crm_message (id, scope, conversation_id, sender, body) values (${id}, ${scope}, ${conversationId}, ${member}, ${content})`;
      await tx`update crm_conversation set last_at = now() where id = ${conversationId}`;
      return !earlier;
    });
  }
  // One notice for a run of unread messages, not one for each.
  if (firstUnread) after(() => noticeNewMessage(scope, open.other, `message:${conversationId}:${open.theirs}`));
  return { id };
}
async function markRead(scope: string, member: string, body: Record<string, unknown>) {
  const id = idOf(body.id);
  const open = await openConversation(scope, member, id);
  if (isFake()) {
    const newest = Math.max(0, ...fakeMessages().filter(m => m.conversationId === id).map(m => m.seq));
    Object.assign(fakeConversations().find(c => c.id === id)!, open.mineIsA ? { readA: newest } : { readB: newest });
  } else if (open.mineIsA) await crmDatabase()`update crm_conversation set read_a = greatest(read_a, coalesce((select max(seq) from crm_message where conversation_id = ${id}), 0)) where id = ${id}`;
  else await crmDatabase()`update crm_conversation set read_b = greatest(read_b, coalesce((select max(seq) from crm_message where conversation_id = ${id}), 0)) where id = ${id}`;
  return { read: true };
}
async function report(scope: string, member: string, body: Record<string, unknown>) {
  const conversationId = idOf(body.id);
  const why = text(body.reason, "a reason", 1000);
  const messageId = idOf(body.message);
  await openConversation(scope, member, conversationId);
  let row: { sender: string; body: string } | undefined;
  if (isFake()) row = fakeMessages().find(m => m.conversationId === conversationId && m.id === messageId);
  else row = (await crmDatabase()`select sender, body from crm_message where conversation_id = ${conversationId} and id = ${messageId}`)[0] as never;
  // Only the other person's messages, and only one a participant can read: reviewers see nothing else from a conversation.
  if (!row || row.sender === member || await isHidden(messageRef(messageId), scope)) throw new CrmProblem("This message is no longer available.", 404);
  await reportTarget(scope, member, { kind: "item", ref: messageRef(messageId) }, why, false, { label: "Private message", href: `/profiles/${encodeURIComponent(row.sender)}`, excerpt: row.body.slice(0, 280) });
  return { message: "Report sent." };
}

const NOTICE = { subject: "You have a new message", text: "Someone sent you a message. Open the app to read it." };
/** Fixed words only: what a person typed never leaves the app in an email. */
export async function noticeNewMessage(scope: string, recipient: string, key: string) {
  if (process.env.PRAMAAN_MESSAGE_EMAIL !== "1") return;
  const to = await memberEmail(recipient, scope).catch(() => undefined);
  if (!to) return;
  if (isFake()) { fakeRows<{ to: string; key: string }>("crm_message_notice").push({ to, key }); return; }
  await sendThroughEmailModule({ to, ...NOTICE }, key).catch(() => undefined);
}
/**
 * The platform's email module, as the email-notices block calls it: the same key never sends twice.
 * Not the `email.send` capability, whose inputs wait in the approvals inbox.
 */
export async function sendThroughEmailModule(mail: { to: string; subject: string; text: string }, key: string, directory = process.env.PRAMAAN_MODULES_DIR ?? "/pramaan-modules") {
  const token = (await readFile(path.join(directory, "token"), "utf8")).trim();
  const body = JSON.stringify(mail);
  await new Promise<void>((resolve, reject) => {
    const sent = request({
      socketPath: path.join(directory, "modules.sock"), path: "/v1/email", method: "POST", timeout: 10_000,
      headers: { authorization: `Bearer ${token}`, "content-type": "application/json", "content-length": Buffer.byteLength(body), "idempotency-key": key },
    }, response => { response.resume(); response.on("end", resolve); response.on("error", reject); });
    sent.on("timeout", () => sent.destroy());
    sent.on("error", reject);
    sent.end(body);
  });
}

export async function messagingAction(scope: string, member: string, body: Record<string, unknown>) {
  switch (body.action) {
    case "start": return start(scope, member, body);
    case "send": return send(scope, member, body);
    case "read": return markRead(scope, member, body);
    case "report": return report(scope, member, body);
    case "block": return moderate(scope, member, { action: "block", ref: body.person });
    default: throw new CrmProblem("Choose an action to continue.");
  }
}

"use client";
import { useEffect, useRef, useState, type FormEvent } from "react";
import { SendHorizontal } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { ConfirmAction } from "@/components/pramaan/confirm-action";
import { EmptyState, ErrorState, LoadingState, SignedOutState, StatusMessage } from "@/components/pramaan/states";
import { api, useResource } from "@/lib/pramaan/client";
import { formatDate } from "@/lib/pramaan/plain";
import type { Conversation, Message, Thread } from "@/lib/pramaan/messaging";

type Token = () => Promise<string>;
const URL_BASE = "/api/pramaan/messages";
const errorText = (e: unknown) => e instanceof Error ? e.message : "Couldn't finish that. Try again.";
const nameOf = (person: Conversation["person"]) => person.name || "Community member";
async function send<T>(body: Record<string, unknown>, getBotCheckToken?: Token) {
  return api<T>(URL_BASE, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ ...body, botCheckToken: await getBotCheckToken?.() }) });
}
function ReportMessage({ conversation, message, getBotCheckToken }: { conversation: string; message: string; getBotCheckToken?: Token }) {
  const [status, setStatus] = useState("");
  const [busy, setBusy] = useState(false);
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (busy) return;
    const form = event.currentTarget;
    setBusy(true); setStatus("");
    try { await send({ action: "report", id: conversation, message, reason: new FormData(form).get("reason") }, getBotCheckToken); form.reset(); setStatus("Report sent."); }
    catch (e) { setStatus(errorText(e)); }
    finally { setBusy(false); }
  }
  return <details className="text-xs"><summary className="cursor-pointer text-muted-foreground">Report message</summary>
    <form onSubmit={submit} className="mt-2 space-y-2">
      <label className="block">Why are you reporting this?<Textarea required maxLength={1000} name="reason" disabled={busy} /></label>
      <Button type="submit" size="sm" variant="outline" disabled={busy}>Send report</Button>
      <StatusMessage text={status} />
    </form>
  </details>;
}
function ThreadView({ id, pollMs, onChanged, onClosed, getBotCheckToken }: { id: string; pollMs: number; onChanged: () => void; onClosed: () => void; getBotCheckToken?: Token }) {
  // ponytail: each poll reads the newest 50, so more than 50 arriving between polls leaves a gap until reopened.
  const { data, error, reload } = useResource<Thread>(`${URL_BASE}?conversation=${encodeURIComponent(id)}`, pollMs);
  const [older, setOlder] = useState<Message[]>([]);
  const [earlier, setEarlier] = useState<string | null>();
  const [draft, setDraft] = useState("");
  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState("");
  const log = useRef<HTMLDivElement>(null);
  const seen = useRef<string>(undefined);
  const newest = data?.messages.at(-1)?.id;
  useEffect(() => {
    if (log.current) log.current.scrollTop = log.current.scrollHeight;
  }, [newest]);
  // Reading marks the conversation read: only for a message this screen is showing to someone.
  useEffect(() => {
    const incoming = data?.messages.filter(m => !m.mine).at(-1)?.id;
    if (!incoming || incoming === seen.current || document.visibilityState !== "visible") return;
    seen.current = incoming;
    void send({ action: "read", id }, getBotCheckToken).then(onChanged, () => { seen.current = undefined; });
  }, [data, id, getBotCheckToken, onChanged]);
  async function submit(event?: FormEvent) {
    event?.preventDefault();
    if (busy || !draft.trim()) return;
    setBusy(true); setStatus("");
    try { await send({ action: "send", id, text: draft }, getBotCheckToken); setDraft(""); reload(); onChanged(); }
    catch (e) { setStatus(errorText(e)); }
    finally { setBusy(false); }
  }
  async function loadEarlier() {
    const before = earlier === undefined ? data?.earlier : earlier;
    if (!before || busy) return;
    setBusy(true);
    try {
      const page = await api<Thread>(`${URL_BASE}?conversation=${encodeURIComponent(id)}&before=${encodeURIComponent(before)}`);
      setOlder(all => [...page.messages, ...all]); setEarlier(page.earlier ?? null);
    } catch (e) { setStatus(errorText(e)); }
    finally { setBusy(false); }
  }
  if (error && (!data || error.status === 404)) return <ErrorState error={error} onRetry={error.status === 404 ? undefined : reload} />;
  if (!data) return <LoadingState label="Loading messages" />;
  const more = earlier === undefined ? data.earlier : earlier;
  const name = nameOf(data.person);
  const shown = [...older.filter(m => !data.messages.some(x => x.id === m.id)), ...data.messages];
  const lastMine = shown.filter(m => m.mine).at(-1)?.id;
  return <section aria-label={`Conversation with ${name}`} className="flex min-w-0 flex-col gap-3 rounded-xl border bg-card text-card-foreground shadow-sm">
    <div className="flex flex-wrap items-center justify-between gap-2 border-b p-3">
      <h2 className="font-serif text-xl">{name}</h2>
      <ConfirmAction label="Block person" title={`Block ${name}?`} description="You won't be able to message each other and this conversation leaves your list. You can unblock them later." variant="outline" disabled={busy} onConfirm={async () => {
        try { await send({ action: "block", person: data.person.ref }, getBotCheckToken); onClosed(); }
        catch (e) { setStatus(errorText(e)); }
      }} />
    </div>
    <div ref={log} role="log" aria-label="Messages" aria-live="polite" className="min-h-[280px] max-h-[55vh] flex-1 space-y-3 overflow-y-auto p-4">
      {more && <Button size="sm" variant="outline" disabled={busy} onClick={() => void loadEarlier()}>Show earlier messages</Button>}
      {!shown.length && <EmptyState title="No messages yet">Say hello.</EmptyState>}
      {shown.map(m => <div key={m.id} className={m.mine ? "ml-auto max-w-[85%] rounded-2xl bg-primary/10 px-4 py-2 text-sm" : "max-w-[85%] space-y-1 text-sm"}>
        <p className="whitespace-pre-wrap break-words">{m.text}</p>
        <p className="text-xs text-muted-foreground"><time dateTime={m.at}>{formatDate(m.at, { time: true })}</time>{m.id === lastMine && m.read && " · Read"}</p>
        {!m.mine && <ReportMessage conversation={id} message={m.id} getBotCheckToken={getBotCheckToken} />}
      </div>)}
    </div>
    <StatusMessage tone="error" text={status} />
    <form className="flex flex-col gap-1 border-t p-3" onSubmit={submit}>
      <Label htmlFor="pramaan-message" className="sr-only">Your message</Label>
      <div className="flex items-stretch gap-2">
        <Textarea
          id="pramaan-message"
          aria-describedby="pramaan-message-hint"
          placeholder="Write a message"
          className="min-h-0 min-w-0 flex-1 resize-none"
          rows={2}
          maxLength={4000}
          value={draft}
          disabled={busy}
          onChange={e => setDraft(e.target.value)}
          onKeyDown={e => {
            // Enter sends. Shift+Enter is a new line. While an input method is composing, Enter belongs to it.
            if (e.key !== "Enter" || e.shiftKey || e.nativeEvent.isComposing) return;
            e.preventDefault();
            if (!busy && draft.trim()) e.currentTarget.form?.requestSubmit();
          }}
        />
        <Button type="submit" className="!h-auto" disabled={busy || !draft.trim()}><SendHorizontal aria-hidden className="size-4" />Send</Button>
      </div>
      <p id="pramaan-message-hint" className="text-xs text-muted-foreground">Enter to send, Shift + Enter for a new line</p>
    </form>
  </section>;
}
/**
 * The conversation list and the open conversation. New messages arrive by polling: `pollMs` for the
 * open conversation, `listPollMs` for the list. Open `?with=<person>` to start or reopen a conversation.
 */
export function MessagingPanel({ pollMs = 3_000, listPollMs = 5_000, getBotCheckToken }: { pollMs?: number; listPollMs?: number; getBotCheckToken?: Token } = {}) {
  const { data, error, reload } = useResource<{ conversations: Conversation[] }>(URL_BASE, listPollMs);
  const [open, setOpen] = useState<string>();
  const [status, setStatus] = useState("");
  const started = useRef(false);
  useEffect(() => {
    const person = new URLSearchParams(window.location.search).get("with");
    if (!person || started.current) return;
    started.current = true;
    send<{ id: string }>({ action: "start", person }, getBotCheckToken).then(({ id }) => { setOpen(id); reload(); }, e => setStatus(errorText(e)));
  }, [getBotCheckToken, reload]);
  if (error?.status === 401) return <SignedOutState reason="Your conversations are private to you." />;
  if (error && !data) return <ErrorState error={error} onRetry={reload} />;
  if (!data) return <LoadingState label="Loading conversations" />;
  return <div className="grid gap-4 md:grid-cols-[18rem_minmax(0,1fr)]">
    <section aria-label="Conversations" className="space-y-2">
      <h2 className="font-serif text-xl">Conversations</h2>
      <StatusMessage tone="error" text={status} />
      {!data.conversations.length && <EmptyState title="No conversations yet">Open someone's profile page and choose Message.</EmptyState>}
      <ul className="space-y-1">{data.conversations.map(c => <li key={c.id}>
        <button aria-current={c.id === open ? "true" : undefined} onClick={() => { setOpen(c.id); setStatus(""); }} className="w-full rounded border p-3 text-left hover:bg-muted aria-[current]:bg-muted">
          <span className="flex items-center justify-between gap-2"><b className="truncate">{nameOf(c.person)}</b>{c.unread > 0 && <span className="pr-pill" data-tone="blue">{c.unread} unread</span>}</span>
          {c.preview && <span className="block truncate text-sm text-muted-foreground">{c.preview}</span>}
        </button>
      </li>)}</ul>
    </section>
    {open
      ? <ThreadView key={open} id={open} pollMs={pollMs} onChanged={reload} onClosed={() => { setOpen(undefined); reload(); }} getBotCheckToken={getBotCheckToken} />
      : <p className="p-4 text-muted-foreground">Choose a conversation to read it.</p>}
  </div>;
}

import { connection } from "next/server";
import { readBody } from "@/lib/pramaan/crm-data";
import { protectMember, socialError, socialResponse } from "@/lib/pramaan/social-context";
import { conversationList, messagingAction, thread } from "@/lib/pramaan/messaging";
export async function GET(request: Request) {
  await connection();
  try {
    const { scope, member } = await protectMember(request);
    const params = new URL(request.url).searchParams;
    const conversation = params.get("conversation");
    return socialResponse(conversation ? await thread(scope, member, conversation, params.get("before")) : await conversationList(scope, member));
  } catch (e) { return socialError(e); }
}
export async function POST(request: Request) {
  try {
    const body = await readBody(request);
    const { scope, member } = await protectMember(request, body);
    return socialResponse(await messagingAction(scope, member, body));
  } catch (e) { return socialError(e); }
}
